theme.css:
/* theme: Boiling Point | A market on edge — oil surging past $100, yields nearing 5%, and a certification fight brewing — rendered as a pressure-cooker of red-hot accents and humid, sweltering weight. */
/* layout: hero=split; political-news=numbered/stack; financial-news=stat/grid-2; entertainment-news=tile/masonry; music-releases=lede/grid-2; stock-analysis=stat/grid-3; outlook=outline/stack */

.diary-page {
  --paper: #1f1a17;
  --paper-alt: #2a231e;
  --ink: #f5ece2;
  --ink-soft: #d9cbbd;
  --muted: #b3a396;
  --accent: #ff6b35;
  --accent-ink: #1a0f08;
  --rule: #44372e;
  --font-display: var(--ff-bebas), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), system-ui, sans-serif;
}

.diary-page[data-hero="split"] .diary-hero {
  background: linear-gradient(180deg, #2a231e 0%, #1f1a17 100%);
  border-bottom: 3px solid #ff6b35;
}

.diary-page[data-hero="split"] .diary-kicker {
  color: #ff6b35;
  letter-spacing: 0.22em;
  font-size: 0.72rem;
}

.diary-page[data-hero="split"] .diary-title {
  font-size: clamp(3.5rem, 9vw, 7rem);
  letter-spacing: 0.04em;
  line-height: 0.9;
  text-transform: uppercase;
  color: #f5ece2;
  text-shadow: 0 4px 24px rgba(255, 107, 53, 0.25);
}

.diary-page[data-hero="split"] .diary-summary {
  font-size: clamp(1.1rem, 1.8vw, 1.3rem);
  line-height: 1.7;
  color: #d9cbbd;
  border-left: 3px solid #ff6b35;
  padding-left: 1.25rem;
}

.diary-page[data-hero="split"] .diary-theme-note {
  color: #b3a396;
  font-size: 0.82rem;
}

.diary-page[data-hero="split"] .diary-theme-name {
  background: #ff6b35;
  color: #1a0f08;
  border-radius: 0;
  padding: 0.15rem 0.6rem;
  font-weight: 700;
}

.diary-page .diary-crumbs a {
  color: #b3a396;
  font-size: 0.8rem;
}

.diary-page .diary-crumbs a:hover {
  color: #ff6b35;
}

.diary-page .diary-toc {
  background: #1f1a17;
  border-bottom: 1px solid #44372e;
}

.diary-page .diary-toc-label {
  color: #b3a396;
  font-size: 0.7rem;
  letter-spacing: 0.2em;
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top {
  color: #b3a396;
  font-size: 0.82rem;
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-top:hover,
.diary-page .diary-toc-link.is-active {
  color: #f5ece2;
}

.diary-page .diary-toc-number {
  color: #ff6b35;
  font-weight: 700;
}

@media (min-width: 1024px) {
  .diary-page .diary-toc-link {
    border-left: 2px solid #44372e;
  }

  .diary-page .diary-toc-link.is-active {
    border-left-color: #ff6b35;
  }
}

.diary-page .diary-section {
  border-top: 1px solid #44372e;
  padding-block: 3.5rem;
}

.diary-page .diary-section-number {
  color: #ff6b35;
  font-weight: 700;
  font-size: 0.75rem;
  letter-spacing: 0.18em;
}

.diary-page .diary-section-title {
  font-family: var(--ff-bebas), sans-serif;
  font-size: clamp(2.2rem, 4.5vw, 3.5rem);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #f5ece2;
  line-height: 1;
}

.diary-page .diary-prose {
  font-size: 1.12rem;
  line-height: 1.8;
  color: #d9cbbd;
}

.diary-page .diary-prose h3 {
  font-family: var(--ff-space-grotesk), sans-serif;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.2em;
  color: #f5ece2;
}

.diary-page .diary-prose h4 {
  font-family: var(--ff-bebas), sans-serif;
  font-size: 1.5rem;
  letter-spacing: 0.05em;
  color: #f5ece2;
}

.diary-page .diary-prose a {
  color: #ff6b35;
  border-bottom-color: currentColor;
  font-size: 0.68em;
  font-weight: 600;
}

.diary-page .diary-prose a:hover {
  color: #f5ece2;
}

.diary-page .diary-prose strong {
  color: #f5ece2;
}

.diary-page .diary-prose ul > li::before {
  background: #ff6b35;
  width: 0.5rem;
}

.diary-page .diary-prose ol > li::marker {
  color: #ff6b35;
}

.diary-page .diary-prose blockquote {
  border-left-color: #ff6b35;
  color: #f5ece2;
}

.diary-page .diary-prose pre {
  background: #2a231e;
  border-color: #44372e;
}

.diary-page[data-card="numbered"] .diary-card-index {
  font-family: var(--ff-bebas), sans-serif;
  font-size: 4rem;
  color: #ff6b35;
  letter-spacing: 0.02em;
  line-height: 0.85;
}

.diary-page[data-card="numbered"] .diary-card-title {
  font-family: var(--ff-bebas), sans-serif;
  font-size: 2rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #f5ece2;
  line-height: 1;
}

.diary-page[data-card="stat"] .diary-card-inner {
  border-top: 3px solid #ff6b35;
  padding-top: 1rem;
}

.diary-page[data-card="stat"] .diary-card-figure {
  font-family: var(--ff-bebas), sans-serif;
  font-size: clamp(2.5rem, 13cqi, 3.75rem);
  color: #ff6b35;
  letter-spacing: 0.03em;
  line-height: 1;
}

.diary-page[data-card="stat"] .diary-card-title {
  font-family: var(--ff-bebas), sans-serif;
  font-size: 1.75rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #f5ece2;
}

.diary-page[data-card="tile"] .diary-card-inner {
  background: #2a231e;
  border: 1px solid #44372e;
}

.diary-page[data-card="tile"] .diary-card-title {
  font-family: var(--ff-bebas), sans-serif;
  font-size: 1.75rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #f5ece2;
}

.diary-page[data-card="lede"] .diary-card-lede {
  border-left: 3px solid #ff6b35;
  font-family: var(--ff-bebas), sans-serif;
  font-size: 1.5rem;
  line-height: 1.2;
  letter-spacing: 0.03em;
  color: #f5ece2;
}

.diary-page[data-card="lede"] .diary-card-title {
  font-family: var(--ff-bebas), sans-serif;
  font-size: 2.25rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #f5ece2;
  line-height: 1;
}

.diary-page[data-card="outline"] .diary-card-inner {
  border: 1px solid #44372e;
  border-radius: 0;
  padding: 1.75rem;
}

.diary-page[data-card="outline"] .diary-card-title {
  font-family: var(--ff-bebas), sans-serif;
  font-size: 2.25rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #ff6b35;
}

.diary-page .diary-card-thread {
  border-color: #ff6b35;
  color: #ff6b35;
  border-radius: 0;
  font-family: var(--ff-space-grotesk), sans-serif;
  font-size: 0.72rem;
  font-weight: 600;
}

.diary-page .diary-card-thread:hover {
  background: #ff6b35;
  color: #1a0f08;
}

.diary-page .diary-stories--stack > .diary-card--plain + .diary-card--plain {
  border-top-color: #44372e;
}

.diary-page .diary-stories--masonry .diary-card {
  margin-bottom: 1.75rem;
}

.diary-page .diary-stories--masonry > .diary-card--plain + .diary-card--plain {
  border-top: 1px solid #44372e;
}

.diary-page .diary-stories--grid-2,
.diary-page .diary-stories--grid-3 {
  gap: 1.75rem;
}

.diary-page .diary-markets-wrap {
  margin-bottom: 2.5rem;
}

.diary-page .diary-markets-label {
  color: #b3a396;
  font-size: 0.7rem;
  letter-spacing: 0.2em;
}

.diary-page .diary-markets {
  gap: 0.875rem;
}

.diary-page .diary-spark {
  background: #2a231e;
  border: 1px solid #44372e;
  border-radius: 0;
  padding: 0.9rem 1rem 0.75rem;
}

.diary-page .diary-spark-label {
  color: #b3a396;
  font-size: 0.72rem;
}

.diary-page .diary-spark-value {
  color: #f5ece2;
  font-size: 1rem;
  font-weight: 700;
}

.diary-page .diary-spark-change {
  font-size: 0.75rem;
  font-weight: 700;
}

.diary-page .diary-spark.is-up .diary-spark-change {
  color: #ff6b35;
}

.diary-page .diary-spark.is-down .diary-spark-change {
  color: #ff6b35;
}

.diary-page .diary-spark .diary-spark-label {
  color: #b3a396;
}

.diary-page .diary-spark .diary-spark-value {
  color: #f5ece2;
}

.diary-page .diary-embed {
  border-radius: 0;
}

.diary-page .diary-footer {
  border-top-color: #44372e;
  color: #b3a396;
}

.diary-page .diary-footer a {
  color: #f5ece2;
}

.diary-page .diary-footer a:hover {
  color: #ff6b35;
}

@media (prefers-color-scheme: dark) {
  .diary-page {
    --paper: #1f1a17;
    --paper-alt: #2a231e;
    --ink: #f5ece2;
    --ink-soft: #d9cbbd;
    --muted: #b3a396;
    --accent: #ff6b35;
    --accent-ink: #1a0f08;
    --rule: #44372e;
    --font-display: var(--ff-bebas), sans-serif;
    --font-body: var(--ff-newsreader), Georgia, serif;
    --font-ui: var(--ff-space-grotesk), system-ui, sans-serif;
  }
}

.diary-page .diary-hero-inner::after {
  content: "";
  display: block;
  width: 100%;
  height: 2px;
  margin-top: 2.5rem;
  background: linear-gradient(90deg, transparent 0%, #ff6b35 50%, transparent 100%);
}

.diary-page .diary-section-head {
  position: relative;
  padding-bottom: 1.25rem;
}

.diary-page .diary-section-head::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 0;
  width: 4rem;
  height: 3px;
  background: #ff6b35;
}

.diary-page[data-section="political-news"] .diary-card-inner {
  padding-left: 1rem;
  border-left: 2px solid transparent;
  transition: border-left-color 150ms ease;
}

.diary-page[data-section="political-news"] .diary-card-inner:hover {
  border-left-color: #ff6b35;
}

.diary-page[data-section="financial-news"] .diary-stories--grid-2 {
  gap: 1.75rem;
}

.diary-page[data-section="financial-news"] .diary-card--stat .diary-card-figure {
  font-size: clamp(3rem, 15cqi, 4.5rem);
}

.diary-page[data-section="entertainment-news"] .diary-card--tile .diary-card-inner {
  border-radius: 0;
}

.diary-page[data-section="music-releases"] .diary-card--lede .diary-card-lede {
  font-size: 1.25rem;
}

.diary-page[data-section="music-releases"] .diary-card--lede .diary-card-title {
  color: #ff6b35;
}

.diary-page[data-section="stock-analysis"] .diary-card--stat .diary-card-inner {
  border-top-width: 4px;
}

.diary-page[data-section="stock-analysis"] .diary-card--stat .diary-card-figure {
  margin-bottom: 0.5rem;
}

.diary-page[data-section="outlook"] .diary-card--outline .diary-card-inner {
  border-left: 4px solid #ff6b35;
}

.diary-page[data-section="outlook"] .diary-card-body {
  font-size: 1.1rem;
  line-height: 1.75;
}

.diary-page .diary-stories--stack {
  gap: 2.5rem;
}

.diary-page .diary-stories--stack > .diary-card--plain + .diary-card--plain {
  padding-top: 2.5rem;
  border-top-width: 2px;
}
